vertex.source:
#version 300 es

// Vertex position in object space coordinates
in vec3 vertexPosition;
// Surface normal at the vertex in object space coordinates
in vec3 vertexNormal;
// Texture coordinates at that vertex
in vec2 vertexTextureCoordinates;

uniform vec4 lightPosition;
uniform bool lightInCamspace;

// Model matrix
uniform mat4 mMatrix;
// View matrix
uniform mat4 vMatrix;
// Projection matrix
uniform mat4 pMatrix;

// Main program for each vertex
void main() {
    vec4 vertexCamSpace = vMatrix * mMatrix * vec4(vertexPosition, 1.0);
    gl_Position = pMatrix * vertexCamSpace;
}

fragment.source:
#version 300 es

// For better performance less precision
precision highp float;

uniform vec4 lightPosition;
uniform bool lightInCamspace;

out vec4 fragColor;

// Main program for each fragment = pixel candidate
void main() {
    fragColor = vec4(1.0, 0.0, 0.0, 1.0);
}

vertex.source:
#version 300 es

// Vertex coordinates in object space for the render quad
in vec3 vertexPosition;
// Texture coordinate for this vertex and the render quad
in vec2 vertexTextureCoordinates;

// Texture coordinate needs to be passed on to the R2T fragment shader
out vec2 fragmentTextureCoordinates;

// Main program for each vertex of the render quad
void main() {
    gl_Position = vec4(vertexPosition, 1.0);
    fragmentTextureCoordinates = vertexTextureCoordinates;
}

fragment.source:
#version 300 es

precision highp float;

// Texture info
uniform sampler2D textureRendered; // A texture sampling unit, which is bound to the render quad texture buffer

// Blur info
uniform float d_max;

// Texture info: input
in vec2 fragmentTextureCoordinates; // Texture coordinates coming from the vertex shader, interpolated through the rasterizer

// Fragment info: output
out vec4 fragColor;

// Main program for each fragment of the render quad
void main() {
    // blur filter info
    float s[12];
    s[0] = -0.10568;    s[1] = -0.07568;    s[2] = -0.042158;
    s[3] = -0.02458;    s[4] = -0.01987456; s[5] = -0.0112458;
    s[6] = 0.0112458;   s[7] = 0.01987456;  s[8] = 0.02458;
    s[9] = 0.042158;    s[10] = 0.07568;    s[11] = 0.10568;

    // calculate blur value
    vec3 blurred = vec3(0., 0., 0.);
    vec2 p = fragmentTextureCoordinates;
    vec2 c = vec2(.5, .5);
    for (int i = 0; i < 12; ++i) {
        float d_i = s[i] * d_max;
        blurred += vec3(texture(textureRendered, (p + normalize(c - p) * d_i)));
    }
    blurred /= 12.;

    // fragment output
    fragColor = vec4(blurred, texture(textureRendered, fragmentTextureCoordinates).a);
}
